import { Injectable, signal, computed, inject } from '@angular/core';
import {
  LogAuditoria,
  EstadisticasAuditoria,
  FiltrosAuditoria,
  AlertaAuditoria,
  PaginacionAuditoria,
  PatronAuditoria,
  ResponseAuditoria
} from '../models/auditoria.models';
import { AuditoriaService } from './auditoria.service';
import { NotificationService } from '../../../../../core/services/notification/notification.service';
import { lastValueFrom } from 'rxjs';
import { UsuarioService } from '../../../../../services/usuario.service';

@Injectable({ providedIn: 'root' })
export class AuditoriaStateService {
  private auditoriaService = inject(AuditoriaService);
  private notificationService = inject(NotificationService);
   private usuarioService = inject(UsuarioService);

  // Signals (estado reactivo)
  private logsSignal = signal<LogAuditoria[]>([]);
  private estadisticasSignal = signal<EstadisticasAuditoria | null>(null);
  private alertasSignal = signal<AlertaAuditoria[]>([]);
  private patronesSignal = signal<PatronAuditoria[]>([]);
  private paginacionSignal = signal<PaginacionAuditoria>({ current_page: 1, per_page: 15, total: 0, last_page: 1 });
  private cargandoSignal = signal(false);
  private filtrosSignal = signal<FiltrosAuditoria>({ pagina: 1, por_pagina: 15 });
  private exportandoSignal = signal(false);
  private usuariosSignal = signal<any[]>([]);

  // Computed (derivados)
  readonly logs = computed(() => this.logsSignal());
  readonly estadisticas = computed(() => this.estadisticasSignal());
  readonly alertas = computed(() => this.alertasSignal());
  readonly patrones = computed(() => this.patronesSignal());
  readonly paginacion = computed(() => this.paginacionSignal());
  readonly cargando = computed(() => this.cargandoSignal());
  readonly exportando = computed(() => this.exportandoSignal());
  readonly totalRegistros = computed(() => this.paginacionSignal().total);
  readonly totalPaginas = computed(() => this.paginacionSignal().last_page);
  readonly usuarios = computed(() => this.usuariosSignal());
  // Getter público para filtros (necesario para export)
  get filtros(): FiltrosAuditoria {
    return this.filtrosSignal();
  }

  constructor() {
     this.cargarUsuarios();
    this.cargarDatosIniciales();
  }

  /**
   * Cargar todos los datos iniciales
   */
  cargarDatosIniciales(): void {
    this.cargarRegistros();
    this.cargarEstadisticas();
    this.cargarAlertas();
  }

  /**
   * Cargar registros con paginación
   */
  async cargarRegistros(filtros?: Partial<FiltrosAuditoria>): Promise<void> {
    this.cargandoSignal.set(true);
    try {
      const nuevosFiltros = { ...this.filtrosSignal(), ...filtros };
      this.filtrosSignal.set(nuevosFiltros);

      const response = await lastValueFrom(this.auditoriaService.listar(nuevosFiltros));
      if (response?.success) {
        this.logsSignal.set(response.data);
        if (response.pagination) {
          this.paginacionSignal.set(response.pagination);
        }
      }
    } catch (error) {
      this.notificationService.showError('Error al cargar registros de auditoría');
    } finally {
      this.cargandoSignal.set(false);
    }
  }

  /**
   * Cargar estadísticas
   */
  async cargarEstadisticas(filtros?: Partial<FiltrosAuditoria>): Promise<void> {
    try {
      const response = await lastValueFrom(this.auditoriaService.obtenerEstadisticas(filtros));
      if (response?.success) {
        this.estadisticasSignal.set(response.data);
      }
    } catch (error) {
      // Silencioso - mantener datos existentes
    }
  }

  /**
   * Cargar alertas
   */
  async cargarAlertas(): Promise<void> {
    try {
      const response = await lastValueFrom(this.auditoriaService.obtenerAlertas());
      if (response?.success) {
        this.alertasSignal.set(response.data);
      }
    } catch (error) {
      // Silencioso
    }
  }

  /**
   * Analizar patrones
   */
  async analizarPatrones(filtros?: Partial<FiltrosAuditoria>): Promise<PatronAuditoria[]> {
    try {
      const filtrosCombinados = { ...this.filtrosSignal(), ...filtros };
      const response = await lastValueFrom(this.auditoriaService.analizarPatrones(filtrosCombinados));
      if (response?.success) {
        this.patronesSignal.set(response.data);
        return response.data;
      }
      return [];
    } catch (error) {
      this.notificationService.showError('Error al analizar patrones');
      return [];
    }
  }

  /**
   * Actualizar filtros y recargar
   */
  actualizarFiltros(nuevosFiltros: Partial<FiltrosAuditoria>): void {
    const actuales = this.filtrosSignal();
    this.filtrosSignal.set({ ...actuales, ...nuevosFiltros });
    this.cargarRegistros();
    this.cargarEstadisticas();
  }

  /**
   * Limpiar todos los filtros
   */
  limpiarFiltros(): void {
    this.filtrosSignal.set({ pagina: 1, por_pagina: 15 });
    this.cargarRegistros();
  }

  /**
   * Cambiar página
   */
  cambiarPagina(pagina: number): void {
    const actuales = this.filtrosSignal();
    this.filtrosSignal.set({ ...actuales, pagina });
    this.cargarRegistros();
  }

  /**
   * Exportar registros
   */
  async exportar(formato: 'csv' | 'json' | 'excel' | 'pdf'): Promise<Blob> {
    this.exportandoSignal.set(true);
    try {
      const filtros = this.filtrosSignal();
      const response = await lastValueFrom(this.auditoriaService.exportar(formato, filtros));
      return response as Blob;
    } finally {
      this.exportandoSignal.set(false);
    }
  }

  /**
   * Obtener detalles de un registro
   */
  async obtenerDetalles(id: number): Promise<LogAuditoria | null> {
    try {
      const response = await lastValueFrom(this.auditoriaService.obtener(id));
      return response?.success ? response.data : null;
    } catch (error) {
      this.notificationService.showError('Error al obtener detalles');
      return null;
    }
  }

  /**
 * Buscar registros
 */
async buscar(termino: string): Promise<LogAuditoria[]> {
  try {
    const response = await lastValueFrom(this.auditoriaService.buscar(termino));
    return response?.success ? response.data : [];
  } catch (error) {
    this.notificationService.showError('Error en la búsqueda');
    return [];
  }
}


async cargarUsuarios(): Promise<void> {
  try {
    const response = await lastValueFrom(this.usuarioService.listar());
    this.usuariosSignal.set(Array.isArray(response) ? response : response?.data || []);
  } catch (error) {
    this.usuariosSignal.set([]);
  }
}

/**
 * Obtener estadísticas del chatbot
 */
async obtenerEstadisticasChatbot(): Promise<any> {
  try {
    const response = await lastValueFrom(this.auditoriaService.obtenerEstadisticas({
      acciones: ['CHAT_USER_MSG', 'CHAT_BOT_MSG', 'CHAT_CODE_REQUEST']
    }));
    return response?.success ? response.data : null;
  } catch (error) {
    this.notificationService.showError('Error al obtener estadísticas del chatbot');
    return null;
  }
}

/**
 * Obtener calificaciones del chat
 */
async obtenerCalificacionesChat(): Promise<any[]> {
  try {
    const response = await lastValueFrom(this.auditoriaService.listar({
      acciones: ['CHAT_FEEDBACK', 'CHAT_CALIFICACION']
    }));
    return response?.success ? response.data : [];
  } catch (error) {
    this.notificationService.showError('Error al obtener calificaciones');
    return [];
  }
}
}
