import { Component, Output, EventEmitter, inject } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { AuditoriaExportService, ExportFormat } from '../../services/auditoria-export.service';
import { AuditoriaStateService } from '../../services/auditoria-state.service';
import { NotificationService } from '../../../../../../core/services/notification/notification.service';

@Component({
  selector: 'app-auditoria-export',
  standalone: true,
  imports: [CommonModule, FormsModule],
  templateUrl: './auditoria-export.component.html',
  styleUrls: ['./auditoria-export.component.less'],
})
export class AuditoriaExportComponent {
  private state = inject(AuditoriaStateService);
  private exportService = inject(AuditoriaExportService);
  private notification = inject(NotificationService);

  @Output() exportStarted = new EventEmitter<ExportFormat>();

  // ✅ Tipado correcto
  formatoSeleccionado: ExportFormat = 'csv';
  exportando = false;

  readonly formatos: Array<{ value: ExportFormat; label: string; icon: string }> = [
    { value: 'csv', label: 'CSV', icon: '📋' },
    { value: 'json', label: 'JSON', icon: '🔧' },
    { value: 'excel', label: 'Excel', icon: '📊' },
    { value: 'pdf', label: 'PDF', icon: '📄' }
  ];

  async exportar(): Promise<void> {
    this.exportando = true;
    this.exportStarted.emit(this.formatoSeleccionado);

    try {
      const filtros = this.state.filtros;
      await this.exportService.exportar(this.formatoSeleccionado, filtros);
      this.notification.showSuccess(`Exportación completada en formato ${this.formatoSeleccionado.toUpperCase()}`);
    } catch (error) {
      this.notification.showError('Error al exportar');
    } finally {
      this.exportando = false;
    }
  }
}
