import { Component, Input, Output, EventEmitter } from '@angular/core';
import { CommonModule } from '@angular/common';
import { LogAuditoria } from '../../models/auditoria.models';
import { ExportFormat } from '../../services/auditoria-export.service';

@Component({
  selector: 'app-auditoria-export-registro-modal',
  standalone: true,
  imports: [CommonModule],
  template: `
    <div class="modal-overlay" *ngIf="isOpen" (click)="onOverlayClick($event)">
      <div class="modal-container modal-export" (click)="$event.stopPropagation()">
        <div class="modal-header">
          <h2>📥 Exportar Registro</h2>
          <button class="modal-close" (click)="cerrar()">✕</button>
        </div>

        <div class="modal-content">
          <!-- Información del registro -->
          <div class="export-info" *ngIf="registro">
            <div class="info-row">
              <span class="info-label">ID:</span>
              <span class="info-value">{{ registro.log_id }}</span>
            </div>
            <div class="info-row">
              <span class="info-label">Usuario:</span>
              <span class="info-value">{{ registro.usuario_nombre || 'Sistema' }}</span>
            </div>
            <div class="info-row">
              <span class="info-label">Acción:</span>
              <span class="info-value">{{ registro.accion }}</span>
            </div>
            <div class="info-row">
              <span class="info-label">Fecha:</span>
              <span class="info-value">{{ registro.fecha | date:'dd/MM/yyyy HH:mm:ss' }}</span>
            </div>
          </div>

          <!-- Opciones de exportación -->
          <div class="export-buttons">
            <h3>Selecciona el formato de exportación:</h3>
            <div class="buttons-grid">
              <button class="btn-export csv" (click)="exportarFormato('csv')">
                <span class="btn-icon">📄</span>
                <span>CSV</span>
              </button>
              <button class="btn-export excel" (click)="exportarFormato('excel')">
                <span class="btn-icon">📊</span>
                <span>Excel</span>
              </button>
              <button class="btn-export pdf" (click)="exportarFormato('pdf')">
                <span class="btn-icon">📑</span>
                <span>PDF</span>
              </button>
            </div>
          </div>
        </div>

        <div class="modal-footer">
          <button class="btn btn-secondary" (click)="cerrar()">Cancelar</button>
        </div>
      </div>
    </div>
  `,
  styles: [`
    .modal-overlay {
      position: fixed;
      top: 0;
      left: 0;
      width: 100%;
      height: 100%;
      background: rgba(0, 0, 0, 0.5);
      display: flex;
      align-items: center;
      justify-content: center;
      z-index: 1000;
    }

    .modal-container {
      background: white;
      border-radius: 12px;
      width: 480px;
      max-width: 90%;
      box-shadow: 0 10px 40px rgba(0, 0, 0, 0.2);
      animation: modalFadeIn 0.3s ease;
    }

    .modal-header {
      display: flex;
      justify-content: space-between;
      align-items: center;
      padding: 20px 24px;
      border-bottom: 1px solid #e9ecef;
      background: linear-gradient(135deg, #1a472a 0%, #2d6a4f 100%);
      border-radius: 12px 12px 0 0;

      h2 {
        margin: 0;
        color: white;
        font-size: 18px;
      }

      .modal-close {
        background: none;
        border: none;
        color: white;
        font-size: 20px;
        cursor: pointer;
        opacity: 0.8;
        transition: opacity 0.2s;

        &:hover {
          opacity: 1;
        }
      }
    }

    .modal-content {
      padding: 24px;
    }

    .export-info {
      background: #f8f9fa;
      border-radius: 8px;
      padding: 16px;
      margin-bottom: 24px;

      .info-row {
        display: flex;
        justify-content: space-between;
        padding: 8px 0;
        border-bottom: 1px solid #e9ecef;

        &:last-child {
          border-bottom: none;
        }

        .info-label {
          font-weight: 600;
          color: #495057;
        }

        .info-value {
          color: #212529;
          font-family: monospace;
        }
      }
    }

    .export-buttons {
      h3 {
        font-size: 14px;
        color: #495057;
        margin-bottom: 16px;
      }

      .buttons-grid {
        display: grid;
        grid-template-columns: repeat(3, 1fr);
        gap: 12px;
      }

      .btn-export {
        display: flex;
        flex-direction: column;
        align-items: center;
        gap: 8px;
        padding: 16px;
        border: 2px solid #e9ecef;
        border-radius: 8px;
        background: white;
        cursor: pointer;
        transition: all 0.2s;

        .btn-icon {
          font-size: 28px;
        }

        span:not(.btn-icon) {
          font-size: 12px;
          font-weight: 500;
        }

        &.csv:hover {
          border-color: #28a745;
          background: #f0fff4;
        }

        &.excel:hover {
          border-color: #007bff;
          background: #f0f8ff;
        }

        &.pdf:hover {
          border-color: #dc3545;
          background: #fff5f5;
        }
      }
    }

    .modal-footer {
      padding: 16px 24px;
      border-top: 1px solid #e9ecef;
      display: flex;
      justify-content: flex-end;

      .btn {
        padding: 8px 20px;
        border-radius: 6px;
        cursor: pointer;
        font-size: 14px;
        transition: all 0.2s;
      }

      .btn-secondary {
        background: #6c757d;
        color: white;
        border: none;

        &:hover {
          background: #5a6268;
        }
      }
    }

    @keyframes modalFadeIn {
      from {
        opacity: 0;
        transform: translateY(-20px);
      }
      to {
        opacity: 1;
        transform: translateY(0);
      }
    }

    :host-context(.dark-theme) {
      .modal-container {
        background: #2d2d2d;
      }

      .export-info {
        background: #3d3d3d;

        .info-label {
          color: #adb5bd;
        }

        .info-value {
          color: #e9ecef;
        }
      }

      .export-buttons .btn-export {
        background: #3d3d3d;
        border-color: #4d4d4d;
        color: #e9ecef;

        &:hover {
          background: #4d4d4d;
        }
      }
    }
  `]
})
export class AuditoriaExportRegistroModalComponent {
  @Input() isOpen = false;
  @Input() registro: LogAuditoria | null = null;
  @Output() cerrarModal = new EventEmitter<void>();
  @Output() exportar = new EventEmitter<ExportFormat>();

  cerrar(): void {
    this.cerrarModal.emit();
  }

  exportarFormato(formato: ExportFormat): void {
    this.exportar.emit(formato);
  }

  onOverlayClick(event: MouseEvent): void {
    if ((event.target as HTMLElement).classList.contains('modal-overlay')) {
      this.cerrar();
    }
  }
}
