import { Component, Output, EventEmitter, inject, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { AuditoriaStateService } from '../../services/auditoria-state.service';
import { FiltrosAuditoria } from '../../models/auditoria.models';
import { UsuarioService } from '../../../../../../services/usuario.service';

@Component({
  selector: 'app-auditoria-filtros',
  standalone: true,
  imports: [CommonModule, FormsModule],
  templateUrl: './auditoria-filtros.component.html',
  styleUrls: ['./auditoria-filtros.component.less'],
})
export class AuditoriaFiltrosComponent implements OnInit {
  private state = inject(AuditoriaStateService);
  private usuarioService = inject(UsuarioService);

  @Output() aplicarFiltros = new EventEmitter<FiltrosAuditoria>();
  @Output() limpiarFiltros = new EventEmitter<void>();

  filtros: FiltrosAuditoria = {};
  mostrarAvanzados = false;
  usuarios: any[] = [];

  readonly accionesDisponibles = ['INSERT', 'UPDATE', 'DELETE', 'SELECT', 'LOGIN', 'LOGOUT', 'ERROR', 'BACKUP',  'CHAT_USER_MSG', 'CHAT_BOT_MSG', 'CHAT_SYSTEM_MSG',
  'CHAT_CODE_REQUEST', 'CHAT_FEEDBACK',
  'CHAT_KB_CREATE', 'CHAT_KB_UPDATE', 'CHAT_KB_DELETE',
  'CHAT_CALIFICACION'];

  ngOnInit(): void {
    this.cargarUsuarios();
  }

  cargarUsuarios(): void {
    this.usuarioService.listar().subscribe({
      next: (response: any) => {
        this.usuarios = Array.isArray(response) ? response : response?.data || [];
      }
    });
  }

  toggleAccion(accion: string): void {
    const acciones = this.filtros.acciones || [];
    const index = acciones.indexOf(accion);
    if (index > -1) {
      acciones.splice(index, 1);
    } else {
      acciones.push(accion);
    }
    this.filtros.acciones = acciones;
  }

  aplicar(): void {
    this.aplicarFiltros.emit(this.filtros);
  }

  limpiar(): void {
    this.filtros = {};
    this.limpiarFiltros.emit();
  }

  toggleAvanzados(): void {
    this.mostrarAvanzados = !this.mostrarAvanzados;
  }
}
