import { Component, Input, OnChanges, SimpleChanges, ViewChild, ElementRef, inject, AfterViewInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { Chart, registerables } from 'chart.js';
import { EstadisticasAuditoria } from '../../models/auditoria.models';

Chart.register(...registerables);

@Component({
  selector: 'app-auditoria-estadisticas',
  standalone: true,
  imports: [CommonModule],
  templateUrl: './auditoria-estadisticas.component.html',
  styleUrls: ['./auditoria-estadisticas.component.less']
})
export class AuditoriaEstadisticasComponent implements OnChanges, AfterViewInit {
  @Input() estadisticas: EstadisticasAuditoria | null = null;

  @ViewChild('accionesChart') accionesChartRef!: ElementRef;
  @ViewChild('tablasChart') tablasChartRef!: ElementRef;
  @ViewChild('horariosChart') horariosChartRef!: ElementRef;

  private accionesChart: Chart | null = null;
  private tablasChart: Chart | null = null;
  private horariosChart: Chart | null = null;

  ngAfterViewInit(): void {
    if (this.estadisticas) {
      setTimeout(() => this.inicializarGraficos(), 200);
    }
  }

  ngOnChanges(changes: SimpleChanges): void {
    if (changes['estadisticas'] && this.estadisticas) {
      this.destruirGraficos();
      setTimeout(() => this.inicializarGraficos(), 200);
    }
  }

  obtenerHoraPico(): string {
    if (!this.estadisticas?.actividad_por_hora || this.estadisticas.actividad_por_hora.length === 0) {
      return 'N/A';
    }
    const maxHora = this.estadisticas.actividad_por_hora.reduce((max, curr) =>
      curr.total > max.total ? curr : max
    );
    return `${maxHora.hora}:00`;
  }

  private inicializarGraficos(): void {
    if (!this.accionesChartRef?.nativeElement) return;
    this.crearGraficoAcciones();
    this.crearGraficoTablas();
    this.crearGraficoHorarios();
  }

  private crearGraficoAcciones(): void {
    if (!this.accionesChartRef?.nativeElement) return;

    const ctx = this.accionesChartRef.nativeElement.getContext('2d');
    const datos = this.estadisticas?.por_accion.slice(0, 5) || [];

    const labels = datos.map(item => item.accion);
    const values = datos.map(item => item.total);
    const colors = ['#4CAF50', '#2196F3', '#FFC107', '#F44336', '#9C27B0'];

    if (this.accionesChart) this.accionesChart.destroy();

    this.accionesChart = new Chart(ctx, {
      type: 'doughnut',
      data: {
        labels: labels.length ? labels : ['Sin datos'],
        datasets: [{
          data: values.length ? values : [1],
          backgroundColor: colors.slice(0, values.length || 1)
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        plugins: {
          legend: {
            position: 'bottom',
            labels: { font: { size: 10 }, boxWidth: 12 }
          }
        },
        cutout: '70%'
      }
    });
  }

  private crearGraficoTablas(): void {
    if (!this.tablasChartRef?.nativeElement) return;

    const ctx = this.tablasChartRef.nativeElement.getContext('2d');
    const datos = this.estadisticas?.por_tabla.slice(0, 5) || [];

    if (this.tablasChart) this.tablasChart.destroy();

    this.tablasChart = new Chart(ctx, {
      type: 'bar',
      data: {
        labels: datos.map(item => item.tabla_afectada) || ['Sin datos'],
        datasets: [{
          label: 'Registros',
          data: datos.map(item => item.total) || [1],
          backgroundColor: '#2196F3',
          borderRadius: 4
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        plugins: {
          legend: { display: false }
        },
        scales: {
          y: { beginAtZero: true, ticks: { font: { size: 9 } } },
          x: { ticks: { font: { size: 9 } } }
        }
      }
    });
  }

private crearGraficoHorarios(): void {
  if (!this.horariosChartRef?.nativeElement) return;

  const ctx = this.horariosChartRef.nativeElement.getContext('2d');
  const horas = Array.from({ length: 24 }, (_, i) => i);
  const valores = this.estadisticas?.actividad_por_hora
    ? horas.map(h => this.estadisticas!.actividad_por_hora.find(d => d.hora === h)?.total || 0)
    : Array(24).fill(0);

  if (this.horariosChart) this.horariosChart.destroy();

  this.horariosChart = new Chart(ctx, {
    type: 'line',
    data: {
      labels: horas.map(h => `${h}:00`),
      datasets: [{
        label: 'Actividad',
        data: valores,
        borderColor: '#4CAF50',
        backgroundColor: 'rgba(76, 175, 80, 0.1)',
        tension: 0.3,
        fill: true,
        pointRadius: 2,
        pointHoverRadius: 4
      }]
    },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      plugins: {
        legend: { display: false }
      },
      scales: {
        y: {
          beginAtZero: true,
          ticks: { font: { size: 9 } }
        },
        x: {
          ticks: {
            font: { size: 9 },
            maxRotation: 45
          }  // ✅ AQUÍ FALTA LA COMA
        }  // ✅ COMA AGREGADA
      }
    }
  });
}

  private destruirGraficos(): void {
    this.accionesChart?.destroy();
    this.tablasChart?.destroy();
    this.horariosChart?.destroy();
    this.accionesChart = null;
    this.tablasChart = null;
    this.horariosChart = null;
  }
}
