import { Component, Input, Output, EventEmitter } from '@angular/core';
import { CommonModule } from '@angular/common';
import { LogAuditoria, PaginacionAuditoria } from '../../models/auditoria.models';
import { TruncatePipe } from '../../pipes/truncate.pipe';
import { RelativeTimePipe } from '../../pipes/relative-time.pipe';
import { FormatIpPipe } from '../../pipes/format-ip.pipe';

@Component({
  selector: 'app-auditoria-tabla',
  standalone: true,
  imports: [CommonModule, TruncatePipe, RelativeTimePipe, FormatIpPipe],
  templateUrl: './auditoria-tabla.component.html',
  styleUrls: ['./auditoria-tabla.component.less'],
})
export class AuditoriaTablaComponent {
  @Input() logs: LogAuditoria[] = [];
  @Input() paginacion: PaginacionAuditoria | null = null;
  @Input() cargando = false;
  @Input() totalPaginas = 1;

  @Output() paginaCambiada = new EventEmitter<number>();
  @Output() verDetalles = new EventEmitter<LogAuditoria>();
  @Output() exportarRegistro = new EventEmitter<LogAuditoria>();
  @Output() verTimeline = new EventEmitter<LogAuditoria>();

  getRowClass(log: LogAuditoria): string {
    const classes = [];
    if (log.nivel === 'ERROR') classes.push('row-error');
    if (log.nivel === 'CRITICAL') classes.push('row-critical');
    if (log.accion === 'DELETE') classes.push('row-delete');
    return classes.join(' ');
  }

  // ✅ Conversión explícita a number
  cambiarPagina(pagina: number | string): void {
    const numPagina = typeof pagina === 'string' ? parseInt(pagina, 10) : pagina;
    if (!isNaN(numPagina) && numPagina >= 1 && numPagina <= this.totalPaginas) {
      this.paginaCambiada.emit(numPagina);
    }
  }

  getRangoPaginas(): (number | string)[] {
    const current = this.paginacion?.current_page || 1;
    const last = this.totalPaginas;
    const delta = 2;
    const range: number[] = [];
    const result: (number | string)[] = [];

    for (let i = 1; i <= last; i++) {
      if (i === 1 || i === last || (i >= current - delta && i <= current + delta)) {
        range.push(i);
      }
    }

    let prev = 0;
    for (const i of range) {
      if (prev !== 0 && i - prev === 2) {
        result.push(prev + 1);
      } else if (prev !== 0 && i - prev !== 1) {
        result.push('...');
      }
      result.push(i);
      prev = i;
    }

    return result;
  }
}
