import { Injectable } from '@angular/core';
import { HttpClient, HttpParams } from '@angular/common/http';
import { Observable } from 'rxjs';
import { environment } from '../../../../../../environments/environment';
import {
  LogAuditoria,
  EstadisticasAuditoria,
  AlertaAuditoria,
  PatronAuditoria,
  FiltrosAuditoria,
  ResponseAuditoria,
  PaginacionAuditoria
} from '../models/auditoria.models';

@Injectable({ providedIn: 'root' })
export class AuditoriaService {
  private readonly API_URL = `${environment.apiUrl}/auditoria`;

  constructor(private http: HttpClient) {}

  /**
   * Listar registros con paginación y filtros
   */
  listar(filtros: FiltrosAuditoria): Observable<ResponseAuditoria<LogAuditoria[]>> {
    let params = new HttpParams();

    Object.entries(filtros).forEach(([key, value]) => {
      if (value !== null && value !== undefined && value !== '') {
        if (Array.isArray(value)) {
          value.forEach(v => params = params.append(`${key}[]`, v));
        } else {
          params = params.set(key, value.toString());
        }
      }
    });

    return this.http.get<ResponseAuditoria<LogAuditoria[]>>(this.API_URL, { params });
  }

  /**
   * Obtener un registro específico
   */
  obtener(id: number): Observable<ResponseAuditoria<LogAuditoria>> {
    return this.http.get<ResponseAuditoria<LogAuditoria>>(`${this.API_URL}/${id}`);
  }

  /**
   * Obtener estadísticas
   */
  obtenerEstadisticas(filtros?: Partial<FiltrosAuditoria>): Observable<ResponseAuditoria<EstadisticasAuditoria>> {
    let params = new HttpParams();

    if (filtros) {
      Object.entries(filtros).forEach(([key, value]) => {
        if (value !== null && value !== undefined) {
          params = params.set(key, value.toString());
        }
      });
    }

    return this.http.get<ResponseAuditoria<EstadisticasAuditoria>>(`${this.API_URL}/estadisticas`, { params });
  }

  /**
   * Obtener alertas de seguridad
   */
  obtenerAlertas(filtros?: Partial<FiltrosAuditoria>): Observable<ResponseAuditoria<AlertaAuditoria[]>> {
    let params = new HttpParams();

    if (filtros) {
      Object.entries(filtros).forEach(([key, value]) => {
        if (value !== null && value !== undefined) {
          params = params.set(key, value.toString());
        }
      });
    }

    return this.http.get<ResponseAuditoria<AlertaAuditoria[]>>(`${this.API_URL}/alertas`, { params });
  }

  /**
   * Analizar patrones
   */
  analizarPatrones(filtros?: Partial<FiltrosAuditoria>): Observable<ResponseAuditoria<PatronAuditoria[]>> {
    let params = new HttpParams();

    if (filtros) {
      Object.entries(filtros).forEach(([key, value]) => {
        if (value !== null && value !== undefined) {
          params = params.set(key, value.toString());
        }
      });
    }

    return this.http.get<ResponseAuditoria<PatronAuditoria[]>>(`${this.API_URL}/patrones`, { params });
  }

  /**
   * Buscar en registros
   */
  buscar(termino: string, filtros?: Partial<FiltrosAuditoria>): Observable<ResponseAuditoria<LogAuditoria[]>> {
    let params = new HttpParams().set('q', termino);

    if (filtros) {
      if (filtros.fecha_inicio) params = params.set('fecha_inicio', filtros.fecha_inicio);
      if (filtros.fecha_fin) params = params.set('fecha_fin', filtros.fecha_fin);
      if (filtros.usuario_id) params = params.set('usuario_id', filtros.usuario_id.toString());
    }

    return this.http.get<ResponseAuditoria<LogAuditoria[]>>(`${this.API_URL}/buscar`, { params });
  }

  /**
   * Exportar registros - Devuelve Blob para descarga
   */
  exportar(formato: 'csv' | 'json' | 'excel' | 'pdf', filtros?: Partial<FiltrosAuditoria>): Observable<Blob> {
    let params = new HttpParams().set('formato', formato);

    if (filtros) {
      if (filtros.fecha_inicio) params = params.set('fecha_inicio', filtros.fecha_inicio);
      if (filtros.fecha_fin) params = params.set('fecha_fin', filtros.fecha_fin);
      if (filtros.usuario_id) params = params.set('usuario_id', filtros.usuario_id.toString());
      if (filtros.tabla_afectada) params = params.set('tabla_afectada', filtros.tabla_afectada);
      if (filtros.keyword) params = params.set('keyword', filtros.keyword);

      if (filtros.acciones && filtros.acciones.length > 0) {
        filtros.acciones.forEach(a => params = params.append('acciones[]', a));
      }
    }

    return this.http.get(`${this.API_URL}/exportar`, {
      params,
      responseType: 'blob'
    });
  }
}
