import { Injectable, inject } from '@angular/core';
import { AuditoriaService } from './auditoria.service';
import { AuditoriaStateService } from './auditoria-state.service';
import { FiltrosAuditoria } from '../models/auditoria.models';
import { saveAs } from 'file-saver';
import { lastValueFrom } from 'rxjs';

export type ExportFormat = 'csv' | 'json' | 'excel' | 'pdf';

export interface ExportStrategy {
  exportar(filtros: FiltrosAuditoria): Promise<void>;
}

@Injectable({ providedIn: 'root' })
export class AuditoriaExportService {
  private auditoriaService = inject(AuditoriaService);
  private state = inject(AuditoriaStateService);

  private estrategias: Map<ExportFormat, ExportStrategy> = new Map();

  constructor() {
    this.registrarEstrategias();
  }

  private registrarEstrategias(): void {
    this.estrategias.set('csv', new CSVExportStrategy(this.auditoriaService));
    this.estrategias.set('json', new JSONExportStrategy(this.auditoriaService));
    this.estrategias.set('excel', new ExcelExportStrategy(this.auditoriaService));
    this.estrategias.set('pdf', new PDFExportStrategy(this.auditoriaService));
  }

  /**
   * Exporta en el formato especificado usando la estrategia correspondiente
   */
  async exportar(formato: ExportFormat, filtros: FiltrosAuditoria): Promise<void> {
    const estrategia = this.estrategias.get(formato);
    if (!estrategia) {
      throw new Error(`Formato no soportado: ${formato}`);
    }
    return estrategia.exportar(filtros);
  }
}

// ============================================
// Estrategias concretas
// ============================================

abstract class BaseExportStrategy implements ExportStrategy {
  protected nombreArchivo(formato: string): string {
    return `auditoria_${Date.now()}.${formato}`;
  }

  abstract exportar(filtros: FiltrosAuditoria): Promise<void>;
}

class CSVExportStrategy extends BaseExportStrategy {
  constructor(private service: AuditoriaService) {
    super();
  }

  async exportar(filtros: FiltrosAuditoria): Promise<void> {
    const blob = await lastValueFrom(this.service.exportar('csv', filtros));
    saveAs(blob, this.nombreArchivo('csv'));
  }
}

class JSONExportStrategy extends BaseExportStrategy {
  constructor(private service: AuditoriaService) {
    super();
  }

  async exportar(filtros: FiltrosAuditoria): Promise<void> {
    const blob = await lastValueFrom(this.service.exportar('json', filtros));
    saveAs(blob, this.nombreArchivo('json'));
  }
}

class ExcelExportStrategy extends BaseExportStrategy {
  constructor(private service: AuditoriaService) {
    super();
  }

  async exportar(filtros: FiltrosAuditoria): Promise<void> {
    const blob = await lastValueFrom(this.service.exportar('excel', filtros));
    saveAs(blob, this.nombreArchivo('xlsx'));
  }
}

class PDFExportStrategy extends BaseExportStrategy {
  constructor(private service: AuditoriaService) {
    super();
  }

  async exportar(filtros: FiltrosAuditoria): Promise<void> {
    const blob = await lastValueFrom(this.service.exportar('pdf', filtros));
    saveAs(blob, this.nombreArchivo('pdf'));
  }
}
