import { Component, OnInit, inject } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { RouterModule } from '@angular/router';
import { AuditoriaStateService } from './services/auditoria-state.service';
import { AuditoriaExportService } from './services/auditoria-export.service';
import { ThemeService } from '../../../../shared/features/home/services/theme.service';
import { NotificationService } from '../../../../core/services/notification/notification.service';
import { ExportFormat } from './services/auditoria-export.service';
import { LogAuditoria } from './models/auditoria.models';
import { TruncatePipe } from './pipes/truncate.pipe';
import { RelativeTimePipe } from './pipes/relative-time.pipe';
import { FormatIpPipe } from './pipes/format-ip.pipe';
import { FormatLogIdPipe } from './pipes/format-log-id.pipe';

import { MenuComponent } from '../../../../layouts/menu/menu.component';
import { HeaderComponent } from '../../../../layouts/header/header.component';
import { FooterComponent } from '../../../../layouts/footer/footer.component';
import { HelpSupportComponent } from '../../../dashboard/components/help-support/help-support.component';
import { AuditoriaFiltrosComponent } from './components/auditoria-filtros/auditoria-filtros.component';
import { AuditoriaEstadisticasComponent } from './components/auditoria-estadisticas/auditoria-estadisticas.component';
import { AuditoriaTablaComponent } from './components/auditoria-tabla/auditoria-tabla.component';
import { AuditoriaExportComponent } from './components/auditoria-export/auditoria-export.component';
import { AuditoriaTimelineComponent } from './components/auditoria-timeline/auditoria-timeline.component';
import { AuditoriaExportRegistroModalComponent } from './components/auditoria-modal-export/auditoria-export-registro-modal.component'; // ✅ Importar

@Component({
  selector: 'app-auditoria',
  templateUrl: './auditoria.component.html',
  styleUrls: ['./auditoria.component.less'],
  standalone: true,
  imports: [
    CommonModule,
    FormsModule,
    RouterModule,
    TruncatePipe,
    RelativeTimePipe,
    FormatIpPipe,
    FormatLogIdPipe,
    MenuComponent,
    HeaderComponent,
    FooterComponent,
    HelpSupportComponent,
    AuditoriaFiltrosComponent,
    AuditoriaEstadisticasComponent,
    AuditoriaTimelineComponent,
    AuditoriaTablaComponent,
    AuditoriaExportComponent,
    AuditoriaExportRegistroModalComponent
  ]
})
export class AuditoriaComponent implements OnInit {
  private state = inject(AuditoriaStateService);
  private exportService = inject(AuditoriaExportService);
  private themeService = inject(ThemeService);
  private notification = inject(NotificationService);

  // Exponer estado
  readonly logs = this.state.logs;
  readonly estadisticas = this.state.estadisticas;
  readonly alertas = this.state.alertas;
  readonly paginacion = this.state.paginacion;
  readonly cargando = this.state.cargando;
  readonly totalRegistros = this.state.totalRegistros;
  readonly totalPaginas = this.state.totalPaginas;

  // UI State
  isSidebarCollapsed = false;
  currentTheme = 'light';
  showHelpSupport = false;
  isMinimized = false;
  showMinimizeNotification = false;
  isSearchOpen = false;
  searchQuery = '';
  searchResults: any[] = [];
  showModalExportIndividual = false;
  registroParaExportar: LogAuditoria | null = null;

  // Notificaciones
  notifications: any[] = [];
  isNotificationsOpen = false;
  isUserMenuOpen = false;

  // ============================================
  // MODALES (AGREGADOS)
  // ============================================

  showModalDetalles = false;
  showModalTimeline = false;
  registroSeleccionado: LogAuditoria | null = null;
  eventosTimeline: any[] = [];
  timelineFiltroUsuario: number | null = null;
  timelineFiltroAccion: string | null = null;
  eventoTimelineSeleccionado: any = null;

  ngOnInit(): void {
    this.themeService.theme$.subscribe(theme => {
      this.currentTheme = theme;
      this.isSidebarCollapsed = theme === 'dark';
    });
  }

  // ============================================
  // SIDEBAR
  // ============================================

  onToggleSidebar(): void {
    this.isSidebarCollapsed = !this.isSidebarCollapsed;
  }

  // ============================================
  // HELP SUPPORT
  // ============================================

  onToggleHelpSupport(): void {
    this.showHelpSupport = !this.showHelpSupport;
  }

  minimizeToBubble(): void {
    this.isMinimized = true;
    this.showMinimizeNotification = true;
    setTimeout(() => this.showMinimizeNotification = false, 3000);
  }

  restoreFromBubble(): void {
    this.isMinimized = false;
  }

  closeBubble(event: MouseEvent): void {
    event.stopPropagation();
    this.showHelpSupport = false;
    this.isMinimized = false;
  }

  handleOverlayClick(event: MouseEvent): void {
    if ((event.target as HTMLElement).classList.contains('modal-overlay-sigpaz')) {
      this.minimizeToBubble();
    }
  }

  // ============================================
  // NOTIFICACIONES Y MENÚ
  // ============================================

  onToggleNotifications(): void {
    this.isNotificationsOpen = !this.isNotificationsOpen;
  }

  onToggleUserMenu(): void {
    this.isUserMenuOpen = !this.isUserMenuOpen;
  }

  onMarkAllAsRead(): void {
    this.notifications.forEach(n => n.read = true);
  }

  // ============================================
  // BÚSQUEDA
  // ============================================

  onOpenSearchModal(): void {
    this.isSearchOpen = true;
  }

  closeSearchModal(): void {
    this.isSearchOpen = false;
    this.searchQuery = '';
    this.searchResults = [];
  }

  performSearch(): void {
    if (!this.searchQuery.trim()) return;
    // Usar el servicio real
    this.state.buscar(this.searchQuery).then(results => {
      this.searchResults = results.map(r => ({
        icon: '📝',
        title: `${r.accion} - ${r.usuario_nombre}`,
        description: r.descripcion
      }));
    });
  }

  clearSearch(): void {
    this.searchQuery = '';
    this.searchResults = [];
  }

  // ============================================
  // ACCIONES DE AUDITORÍA
  // ============================================

  aplicarFiltros(filtros: any): void {
    this.state.actualizarFiltros(filtros);
  }

  limpiarFiltros(): void {
    this.state.limpiarFiltros();
  }

  cambiarPagina(pagina: number): void {
    this.state.cambiarPagina(pagina);
  }

  async exportar(formato: ExportFormat): Promise<void> {
    try {
      const filtros = this.state.filtros;
      await this.exportService.exportar(formato, filtros);
      this.notification.showSuccess(`Exportación completada en formato ${formato.toUpperCase()}`);
    } catch (error) {
      console.error('Error al exportar:', error);
      this.notification.showError('Error al exportar');
    }
  }

  // ============================================
  // MODALES - DETALLES
  // ============================================

  verDetalles(log: LogAuditoria): void {
    this.state.obtenerDetalles(log.log_id).then(detalle => {
      if (detalle) {
        this.registroSeleccionado = detalle;
        this.showModalDetalles = true;
      }
    });
  }

  cerrarModalDetalles(): void {
    this.showModalDetalles = false;
    this.registroSeleccionado = null;
  }

  exportarRegistro(log: LogAuditoria): void {
    this.notification.showInfo(`Exportando registro ${log.log_id}`);
    // Implementar exportación de un solo registro si es necesario
  }

  // ============================================
  // MODALES - TIMELINE
  // ============================================

  onEventoTimelineSeleccionado(evento: any): void {
  console.log('Evento seleccionado en timeline:', evento);
  // Aquí puedes abrir el modal de detalles o realizar otra acción
}

verTimeline(log: LogAuditoria): void {
  this.registroSeleccionado = log;
  this.showModalTimeline = true;
}

  cargarEventosTimeline(): void {
    if (!this.registroSeleccionado) return;

    const filtros = {
      fecha_inicio: new Date(new Date(this.registroSeleccionado.fecha).getTime() - 3600000).toISOString(),
      fecha_fin: new Date(new Date(this.registroSeleccionado.fecha).getTime() + 3600000).toISOString(),
      usuario_id: this.timelineFiltroUsuario,
      acciones: this.timelineFiltroAccion ? [this.timelineFiltroAccion] : undefined,
      por_pagina: 50
    };

    this.state.cargarRegistros(filtros).then(() => {
      const logs = this.state.logs();
      this.eventosTimeline = logs.map(l => ({
        id: l.log_id,
        tipo: l.log_id === this.registroSeleccionado?.log_id ? 'principal' : 'relacionado',
        icon: this.getAccionIcon(l.accion),
        usuario: l.usuario_nombre || 'Sistema',
        usuario_id: l.usuario_id,
        accion: l.accion,
        descripcion: l.descripcion,
        fecha: l.fecha,
        ip: l.ip_origen,
        tabla: l.tabla_afectada,
        nivel: l.nivel
      }));
    });
  }

cerrarModalTimeline(): void {
  this.showModalTimeline = false;
  this.registroSeleccionado = null;
}

  actualizarTimeline(): void {
    this.cargarEventosTimeline();
  }

  calcularPosicionTimeline(fecha: string): number {
    if (!this.eventosTimeline.length || !this.registroSeleccionado) return 0;

    const fechas = this.eventosTimeline.map(e => new Date(e.fecha).getTime());
    const fechaEvento = new Date(fecha).getTime();
    const fechaCentral = new Date(this.registroSeleccionado.fecha).getTime();
    const minFecha = fechaCentral - 3600000;
    const maxFecha = fechaCentral + 3600000;
    const total = maxFecha - minFecha;
    const desdeInicio = fechaEvento - minFecha;

    if (total === 0) return 50;
    let porcentaje = (desdeInicio / total) * 100;
    return Math.max(0, Math.min(100, porcentaje));
  }

  seleccionarEventoTimeline(evento: any): void {
    this.eventoTimelineSeleccionado = evento;
  }

  getAccionIcon(accion: string): string {
    const icons: Record<string, string> = {
      INSERT: '➕', UPDATE: '✏️', DELETE: '🗑️', SELECT: '🔍',
      LOGIN: '🔑', LOGOUT: '🚪', ERROR: '❌', BACKUP: '💾'
    };
    return icons[accion] || '📝';
  }

   /**
   * Exportar un registro individual - Abre el modal
   */
  exportarRegistroIndividual(log: LogAuditoria): void {
    this.registroParaExportar = log;
    this.showModalExportIndividual = true;
  }


  /**
   * Exportar un registro específico (llamado desde el modal)
   */
  async exportarRegistroEspecifico(formato: ExportFormat): Promise<void> {
    if (!this.registroParaExportar) return;

    try {
      // Crear filtros específicos para este registro
      const filtros = {
        log_id: this.registroParaExportar.log_id,
        fecha_inicio: this.registroParaExportar.fecha,
        fecha_fin: this.registroParaExportar.fecha
      };

      await this.exportService.exportar(formato, filtros);
      this.notification.showSuccess(`Registro ${this.registroParaExportar.log_id} exportado en formato ${formato.toUpperCase()}`);
      this.cerrarModalExportIndividual();
    } catch (error) {
      console.error('Error al exportar registro:', error);
      this.notification.showError('Error al exportar el registro');
    }
  }

  cerrarModalExportIndividual(): void {
    this.showModalExportIndividual = false;
    this.registroParaExportar = null;
  }
}
